usage.code:
import { MorphSlider } from "solen-design/react";

const items = [
  { image: "/slides/dune.jpg", caption: "Dune" },
  { image: "/slides/ocean.jpg", caption: "Ocean" },
  { image: "/slides/forest.jpg", caption: "Forest" }
];

<MorphSlider
  items={items}
  startIndex={0}
  transition="melt"
  duration={1.1}
  ease="power2.inOut"
  intensity={0.55}
  scale={2.4}
  aberration={0.35}
  drift={0.4}
  autoplay={false}
  autoplayDelay={4}
  loop={true}
  radius={16}
  overlayColor="#000000"
  showCaptions={true}
  showControls={true}
  showIndicators={true}
/>
